import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo2: HistoricalDocument = {
  id: 'codigo-manu-capitulo-2',
  title: 'Capítulo II',
  subtitle: 'Da Educação, dos Sacramentos e dos Deveres do Estudante',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Regula os sacramentos, os deveres do estudante brâmane e os ritos de passagem na vida do duas-vezes-nascido.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo II',
      type: 'articles',
      articles: [
        { id: 'cm-2-1', number: 'Verso 1', text: `Aprende aquela lei sagrada que é seguida pelos homens eruditos (no Veda) e assentida em seus corações pelos virtuosos, que estão sempre isentos de ódio e afeto desordenado.` },
        { id: 'cm-2-2', number: 'Verso 2', text: `Agir apenas por desejo de recompensas não é louvável, no entanto, uma isenção desse desejo não se (encontra) neste (mundo): pois sobre (esse) desejo está fundamentado o estudo do Veda e a realização das ações, prescritas pelo Veda.` },
        { id: 'cm-2-3', number: 'Verso 3', text: `O desejo (por recompensas), de fato, tem sua raiz na concepção de que um ato pode rendê-las, e em consequência (dessa) concepção sacrifícios são realizados; votos e as leis que prescrevem restrições são todos declarados como sendo mantidos através da ideia de que darão frutos.` },
        { id: 'cm-2-4', number: 'Verso 4', text: `Nem um único ato aqui (embaixo) parece jamais ser feito por um homem livre de desejo; pois o que quer que (o homem) faça, é (o resultado do) impulso do desejo.` },
        { id: 'cm-2-5', number: 'Verso 5', text: `Aquele que persiste em cumprir estes (deveres prescritos) da maneira correta, alcança o estado imortal e mesmo nesta (vida) obtém (a satisfação de) todos os desejos que possa ter concebido.` },
        { id: 'cm-2-6', number: 'Verso 6', text: `Todo o Veda é a (primeira) fonte da lei sagrada, a seguir a tradição e a conduta virtuosa daqueles que conhecem o (Veda ademais), também os costumes dos homens santos, e (finalmente) a satisfação pessoal.` },
        { id: 'cm-2-7', number: 'Verso 7', text: `Qualquer lei que tenha sido ordenada para qualquer (pessoa) por Manu, essa foi integralmente declarada no Veda: pois aquele (sábio era) onisciente.` },
        { id: 'cm-2-8', number: 'Verso 8', text: `Mas um homem erudito, após escrutinar totalmente tudo isso com o olho do conhecimento, deve, de acordo com a autoridade dos textos revelados, estar focado na (realização de) seus deveres.` },
        { id: 'cm-2-9', number: 'Verso 9', text: `Pois aquele homem que obedece à lei prescrita nos textos revelados e na tradição sagrada, ganha fama neste (mundo) e, após a morte, bem-aventurança insuperável.` },
        { id: 'cm-2-10', number: 'Verso 10', text: `Mas por *Sruti* (revelação) entende-se o Veda, e por *Smriti* (tradição) os Institutos da lei sagrada: esses dois não devem ser questionados em qualquer matéria, visto que a partir desses dois a lei sagrada brilhou.` },
        { id: 'cm-2-11', number: 'Verso 11', text: `Todo homem duas-vezes-nascido, que, confiando nos Institutos da dialética, trata com desprezo essas duas fontes (da lei), deve ser expulso pelos virtuosos, como um ateu e um escarnecedor do Veda.` },
        { id: 'cm-2-12', number: 'Verso 12', text: `O Veda, a tradição sagrada, os costumes dos homens virtuosos, e o próprio prazer, eles declaram ser visivelmente os quatro meios de definir a lei sagrada.` },
        { id: 'cm-2-13', number: 'Verso 13', text: `O conhecimento da lei sagrada é prescrito para aqueles que não são dados à aquisição de riqueza e à gratificação de seus desejos; para aqueles que buscam o conhecimento da lei sagrada a autoridade suprema é a revelação (*Sruti*).` },
        { id: 'cm-2-14', number: 'Verso 14', text: `Mas quando dois textos sagrados (*Sruti*) são conflitantes, ambos são tidos como lei; pois ambos são pronunciados pelos sábios (como sendo) lei válida.` },
        { id: 'cm-2-15', number: 'Verso 15', text: `(Assim) o sacrifício (*Agnihotra*) pode ser (opcionalmente) realizado, a qualquer tempo após o sol ter nascido, antes que ele tenha nascido, ou quando nem o sol nem as estrelas são visíveis; isso (é declarado) pelos textos Védicos.` },
        { id: 'cm-2-16', number: 'Verso 16', text: `Sabe que aquele para quem (a realização das) cerimônias começando com o rito da impregnação (*Garbhadhana*) e terminando com o rito fúnebre (*Antyeshti*) é prescrito, enquanto fórmulas sagradas estão sendo recitadas, tem o direito (de estudar) estes Institutos, mas nenhum outro homem absolutamente.` },
        { id: 'cm-2-17', number: 'Verso 17', text: `Aquela terra, criada pelos deuses, que jaz entre os dois rios divinos Sarasvati e Drishadvati, os (sábios) chamam de Brahmavarta.` },
        { id: 'cm-2-18', number: 'Verso 18', text: `O costume transmitido em sucessão regular (desde tempos imemoriais) entre as (quatro principais) castas (*varna*) e as (raças) mistas daquele país, é chamado de conduta dos homens virtuosos.` },
        { id: 'cm-2-19', number: 'Verso 19', text: `A planície dos Kurus, o (país dos) Matsyas, Pankalas, e Surasenakas, estes (formam), de fato, o país dos Brahmarshis (sábios Brahmânicos, que se classifica) imediatamente após Brahmavarta.` },
        { id: 'cm-2-20', number: 'Verso 20', text: `De um *Brahmana*, nascido naquele país, que todos os homens na terra aprendam seus diversos usos.` },
        { id: 'cm-2-21', number: 'Verso 21', text: `Aquele (país) que (jaz) entre o Himavat e o Vindhya (montanhas) a leste de Prayaga e a oeste de Vinasana (o lugar onde o rio Sarasvati desaparece) é chamado Madhyadesa (a região central).` },
        { id: 'cm-2-22', number: 'Verso 22', text: `Mas (a extensão) entre aquelas duas montanhas (recém-mencionadas), que (se estende) até os oceanos oriental e ocidental, os sábios chamam Aryavarta (o país dos Arianos).` },
        { id: 'cm-2-23', number: 'Verso 23', text: `Aquela terra onde o antílope negro vagueia naturalmente, deve-se saber ser adequada para a realização de sacrifícios; (a extensão) diferente dessa (é) o país dos Mlekkhas (bárbaros).` },
        { id: 'cm-2-24', number: 'Verso 24', text: `Que os homens duas-vezes-nascidos busquem habitar naqueles (países acima mencionados); mas um *Sudra*, aflito por subsistência, pode residir em qualquer lugar.` },
        { id: 'cm-2-25', number: 'Verso 25', text: `Assim foi a origem da lei sagrada sucintamente descrita para ti e a origem deste universo; aprende (agora) os deveres das castas (*varna*).` },
        { id: 'cm-2-26', number: 'Verso 26', text: `Com ritos sagrados, prescritos pelo Veda, deve a cerimônia na concepção e outros sacramentos ser realizada para os homens duas-vezes-nascidos, os quais santificam o corpo e purificam (do pecado) nesta (vida) e após a morte.` },
        { id: 'cm-2-27', number: 'Verso 27', text: `Por oblações queimadas durante a gravidez (da mãe), pelo *Gatakarman* (a cerimônia após o nascimento), o *Kauda* (tonsura), e o *Maungibandhana* (a amarração do cinto sagrado de grama Munga) é a mácula, derivada de ambos os pais, removida dos homens duas-vezes-nascidos.` },
        { id: 'cm-2-28', number: 'Verso 28', text: `Pelo estudo do Veda, por votos, por oblações queimadas, pela (recitação de) textos sagrados, pela (aquisição da) tríplice ciência sagrada, pela oferenda (aos deuses, Rishis, e manes), pela (procriação de) filhos, pelos grandes sacrifícios, e por ritos (*Srauta*) este corpo (humano) é feito apto para (união com) Brahman.` },
        { id: 'cm-2-29', number: 'Verso 29', text: `Antes que o cordão umbilical seja cortado, o *Gatakarman* (rito de nascimento) deve ser realizado para uma (criança) do sexo masculino; e enquanto fórmulas sagradas estão sendo recitadas, ele deve ser alimentado com ouro, mel, e manteiga.` },
        { id: 'cm-2-30', number: 'Verso 30', text: `Mas que (o pai realize ou) faça ser realizado o *Namadheya* (o rito de nomear a criança), no décimo ou décimo segundo (dia após o nascimento), ou em um dia lunar de sorte, em um *muhurta* de sorte, sob uma constelação auspiciosa.` },
        { id: 'cm-2-31', number: 'Verso 31', text: `Que (a primeira parte do) nome de um *Brahmana* (denote algo) auspicioso, o de um *Kshatriya* seja conectado com poder, e o de um *Vaisya* com riqueza, mas o de um *Sudra* (expresse algo) desprezível.` },
        { id: 'cm-2-32', number: 'Verso 32', text: `(A segunda parte do nome) de um *Brahmana* deverá ser (uma palavra) implicando felicidade, o de um *Kshatriya* (uma palavra) implicando proteção, o de um *Vaisya* (um termo) expressivo de prosperidade, e o de um *Sudra* (uma expressão) denotando serviço.` },
        { id: 'cm-2-33', number: 'Verso 33', text: `Os nomes das mulheres devem ser fáceis de pronunciar, não implicar nada terrível, possuir um significado claro, ser agradáveis e auspiciosos, terminar em vogais longas, e conter uma palavra de benção.` },
        { id: 'cm-2-34', number: 'Verso 34', text: `No quarto mês o *Nishkramana* (a primeira saída da casa) da criança deve ser realizado, no sexto mês o *Annaprasana* (primeira alimentação com arroz), e opcionalmente (qualquer outra) cerimônia auspiciosa exigida pelo (costume da) família.` },
        { id: 'cm-2-35', number: 'Verso 35', text: `De acordo com o ensinamento dos textos revelados, o *Kudakarman* (tonsura) deve ser realizado, por causa do mérito espiritual, por todos os homens duas-vezes-nascidos no primeiro ou terceiro ano.` },
        { id: 'cm-2-36', number: 'Verso 36', text: `No oitavo ano após a concepção, deve-se realizar a iniciação (*upanayana*) de um *Brahmana*, no décimo primeiro após a concepção (a) de um *Kshatriya*, mas no décimo segundo a de um *Vaisya*.` },
        { id: 'cm-2-37', number: 'Verso 37', text: `(A iniciação) de um *Brahmana* que deseja proficiência no aprendizado sagrado deve ocorrer no quinto (ano após a concepção), (a) de um *Kshatriya* que deseja tornar-se poderoso no sexto, (e a) de um *Vaisya* que anseia por (sucesso em seus) negócios no oitavo.` },
        { id: 'cm-2-38', number: 'Verso 38', text: `O (tempo para a) *Savitri* (iniciação) de um *Brahmana* não passa até a conclusão do décimo sexto ano (após a concepção), a de um *Kshatriya* até a conclusão do vigésimo segundo, e a de um *Vaisya* até a conclusão do vigésimo quarto.` },
        { id: 'cm-2-39', number: 'Verso 39', text: `Após esses (períodos os homens destas) três (castas) que não receberam o sacramento no tempo adequado, tornam-se *Vratyas* (párias), excluídos da *Savitri* (iniciação) e desprezados pelos Arianos.` },
        { id: 'cm-2-40', number: 'Verso 40', text: `Com tais homens, se eles não tiverem sido purificados de acordo com a regra, que nenhum *Brahmana* jamais, mesmo em tempos de aflição, forme uma conexão quer através do Veda quer por casamento.` },
        { id: 'cm-2-41', number: 'Verso 41', text: `Que os estudantes, de acordo com a ordem (de suas castas), vistam (como vestes superiores) as peles de antílopes negros, cervos pintados, e bodes, e (vestes inferiores) feitas de cânhamo, linho ou lã.` },
        { id: 'cm-2-42', number: 'Verso 42', text: `O cinto de um *Brahmana* consistirá em um cordão triplo de grama Munga, liso e macio; (o) de um *Kshatriya*, de uma corda de arco, feita de fibras Murva; (o) de um *Vaisya*, de fios de cânhamo.` },
        { id: 'cm-2-43', number: 'Verso 43', text: `Se grama Munga (e assim por diante) não for obtível, (os cintos) podem ser feitos de (fibras de) Kusa, Asmantaka, e Balbaga, com um único nó triplo, ou com três ou cinco (nós de acordo com o costume da família).` },
        { id: 'cm-2-44', number: 'Verso 44', text: `O cordão sacrificial de um *Brahmana* será feito de algodão, (será) torcido para a direita, (e consistirá) de três fios, o de um *Kshatriya* de fios de cânhamo, (e) o de um *Vaisya* de fios de lã.` },
        { id: 'cm-2-45', number: 'Verso 45', text: `Um *Brahmana* deverá (carregar), de acordo com a lei sagrada, um cajado de Bilva ou Palasa; um *Kshatriya*, de Vata ou Khadira; (e) um *Vaisya*, de Pilu ou Udumbara.` },
        { id: 'cm-2-46', number: 'Verso 46', text: `O cajado de um *Brahmana* deverá ser feito de tal comprimento que alcance a ponta de seu cabelo; o de um *Kshatriya*, que alcance sua testa; (e) o de um *Vaisya*, que alcance (a ponta de seu) nariz.` },
        { id: 'cm-2-47', number: 'Verso 47', text: `Que todos os cajados sejam retos, sem mácula, bonitos de se olhar, com probabilidade de não aterrorizar os homens, com sua casca perfeita, ilesos pelo fogo.` },
        { id: 'cm-2-48', number: 'Verso 48', text: `Tendo tomado um cajado de acordo com sua escolha, tendo reverenciado o sol e andado ao redor do fogo, virando sua mão direita em direção a ele, (o estudante) deve pedir esmolas de acordo com a regra prescrita.` },
        { id: 'cm-2-49', number: 'Verso 49', text: `Um *Brahmana* iniciado deve mendigar, começando (seu pedido com a palavra) senhora (*bhavati*); um *Kshatriya*, colocando (a palavra) senhora no meio, mas um *Vaisya*, colocando-a no fim (da fórmula).` },
        { id: 'cm-2-50', number: 'Verso 50', text: `Que ele primeiro peça alimento à sua mãe, ou à sua irmã, ou à sua própria tia materna, ou a (alguma outra) fêmea que não o desonrará (por uma recusa).` },
        { id: 'cm-2-51', number: 'Verso 51', text: `Tendo coletado tanto alimento quanto necessário (de várias pessoas), e tendo-o anunciado sem dolo ao seu professor, que ele coma, voltando sua face para o leste, e tendo-se purificado sorvendo água.` },
        { id: 'cm-2-52', number: 'Verso 52', text: `(Sua refeição proporcionará) vida longa, se ele come de frente para o leste; fama, se ele se volta para o sul; prosperidade, se ele se volta para o oeste; veracidade, se ele fica de frente para o leste.` },
        { id: 'cm-2-53', number: 'Verso 53', text: `Que um homem duas-vezes-nascido sempre coma seu alimento com a mente concentrada, após realizar uma ablução; e depois que ele tiver comido, que ele devidamente se limpe com água e borrife as cavidades (de sua cabeça).` },
        { id: 'cm-2-54', number: 'Verso 54', text: `Que ele sempre reverencie seu alimento, e o coma sem desprezo; quando o vir, que se alegre, mostre uma face comprazida, e ore para que ele possa sempre obtê-lo.` },
        { id: 'cm-2-55', number: 'Verso 55', text: `O alimento, que é sempre reverenciado, dá força e vigor viril; mas comido irreverentemente, destrói a ambos.` },
        { id: 'cm-2-56', number: 'Verso 56', text: `Que ele não dê a nenhum homem o que ele deixa, e cuide-se para não comer entre (os dois horários de refeição); que ele não coma em demasia, nem vá a lugar algum sem ter-se purificado (após sua refeição).` },
        { id: 'cm-2-57', number: 'Verso 57', text: `O comer excessivo é prejudicial à saúde, à fama, e à (bem-aventurança no) céu; previne (a aquisição de) mérito espiritual, e é odioso entre os homens; deve-se, por estas razões, evitá-lo cuidadosamente.` },
        { id: 'cm-2-58', number: 'Verso 58', text: `Que um *Brahmana* sempre sorva água da parte da mão (*tirtha*) sagrada para Brahman, ou daquela sagrada para Ka (Pragapati), ou daquela sagrada para os deuses, nunca daquela sagrada para os manes.` },
        { id: 'cm-2-59', number: 'Verso 59', text: `Eles chamam (a parte) na base do polegar o *tirtha* sagrado para Brahman, aquela na base do dedo (mínimo) (o *tirtha*) sagrado para Ka (Pragapati), (aquela) nas pontas (dos dedos, o *tirtha*) sagrado para os deuses, e aquela abaixo (entre o indicador e o polegar, o *tirtha*) sagrado para os manes.` },
        { id: 'cm-2-60', number: 'Verso 60', text: `Que ele primeiro sorva água três vezes; a seguir limpe duas vezes sua boca; e, por último, toque com água as cavidades (da cabeça), (o assento da) alma e a cabeça.` },
        { id: 'cm-2-61', number: 'Verso 61', text: `Aquele que conhece a lei sagrada e busca a pureza deverá sempre realizar o rito de sorver com água nem quente nem espumante, com o *tirtha* (prescrito), em um lugar solitário, e voltando-se para o leste ou para o norte.` },
        { id: 'cm-2-62', number: 'Verso 62', text: `Um *Brahmana* é purificado por água que alcança o seu coração, um *Kshatriya* por água alcançando sua garganta, um *Vaisya* por água tomada em sua boca, (e) um *Sudra* por água tocada com a extremidade (de seus lábios).` },
        { id: 'cm-2-63', number: 'Verso 63', text: `Um homem duas-vezes-nascido é chamado *upavitin* quando seu braço direito é levantado (e o cordão sacrificial ou a veste, passada sob ele, descansa no ombro esquerdo); (quando seu braço) esquerdo é levantado (e o cordão, ou a veste, passada sob ele, descansa no ombro direito, ele é chamado) *prakinavitin*; e *nivitin* quando pende (reto) do pescoço.` },
        { id: 'cm-2-64', number: 'Verso 64', text: `Seu cinto, a pele (que serve como sua veste superior), seu cajado, seu cordão sacrificial, (e) seu pote de água ele deve atirar na água, quando tiverem sido danificados, e pegar outros, recitando fórmulas sagradas.` },
        { id: 'cm-2-65', number: 'Verso 65', text: `(A cerimônia chamada) *Kesanta* (corte de cabelo) é ordenada para um *Brahmana* no décimo sexto ano (a partir da concepção); para um *Kshatriya*, no vigésimo segundo; e para um *Vaisya*, dois (anos) mais tarde do que isso.` },
        { id: 'cm-2-66', number: 'Verso 66', text: `Toda esta série (de cerimônias) deve ser realizada para as fêmeas (também), a fim de santificar o corpo, no tempo adequado e na ordem adequada, mas sem (a recitação de) textos sagrados.` },
        { id: 'cm-2-67', number: 'Verso 67', text: `A cerimônia nupcial é declarada ser o sacramento Védico para as mulheres (e ser igual à iniciação), servir ao marido (equivalente à) residência na (casa do) professor, e os deveres domésticos (o mesmo) que a adoração (diária) do fogo sagrado.` },
        { id: 'cm-2-68', number: 'Verso 68', text: `Assim foi descrita a regra para a iniciação dos duas-vezes-nascidos, que indica um (novo) nascimento, e santifica; aprende (agora) a que deveres eles devem depois aplicar-se.` },
        { id: 'cm-2-69', number: 'Verso 69', text: `Tendo realizado o (rito de) iniciação, o professor deve primeiro instruir o (pupilo) nas (regras de) purificação pessoal, de conduta, da adoração do fogo, e das devoções do crepúsculo.` },
        { id: 'cm-2-70', number: 'Verso 70', text: `Mas (um estudante) que está prestes a começar o Estudo (do Veda), deverá receber instrução, após ele ter sorvido água de acordo com os Institutos (da lei sagrada), ter feito o *Brahmangali*, (ter colocado) uma veste limpa, e ter trazido seus órgãos sob devido controle.` },
        { id: 'cm-2-71', number: 'Verso 71', text: `No princípio e no final de (uma lição no) Veda ele deve sempre abraçar ambos os pés de seu professor, (e) ele deve estudar, juntando suas mãos; isso é chamado o *Brahmangali* (juntar as palmas pela causa do Veda).` },
        { id: 'cm-2-72', number: 'Verso 72', text: `Com as mãos cruzadas ele deve abraçar (os pés) do professor, e tocar o (pé) esquerdo com sua (mão) esquerda, o (pé) direito com sua (mão) direita.` },
        { id: 'cm-2-73', number: 'Verso 73', text: `Mas àquele que está prestes a começar a estudar, o professor sempre incansável, deve dizer: Oh, recita! Ele deverá parar (quando o professor disser): Que haja uma parada!` },
        { id: 'cm-2-74', number: 'Verso 74', text: `Que ele sempre pronuncie a sílaba Om no princípio e no final de (uma lição no) Veda; (pois) a menos que a sílaba Om preceda (a lição) escapará (dele), e a menos que ela siga, ela desaparecerá.` },
        { id: 'cm-2-75', number: 'Verso 75', text: `Sentado em (lâminas de grama Kusa) com suas pontas para o leste, purificado por *Pavitras* (lâminas de grama Kusa), e santificado por três supressões da respiração (*Pranayama*), ele é digno (de pronunciar) a sílaba Om.` },
        { id: 'cm-2-76', number: 'Verso 76', text: `Pragapati (o senhor das criaturas) ordenhou (por assim dizer) dos três Vedas os sons A, U, e M, e (as *Vyahritis*) *Bhuh*, *Bhuvah*, *Svah*.` },
        { id: 'cm-2-77', number: 'Verso 77', text: `Ademais dos três Vedas Pragapati, que habita no mais alto céu (*Parameshthin*), ordenhou (por assim dizer) aquela estrofe-*Rik*, sagrada para Savitri (*Savitri*), que começa com a palavra *tad*, um pé de cada.` },
        { id: 'cm-2-78', number: 'Verso 78', text: `Um *Brahmana*, erudito no Veda, que recita durante ambos os crepúsculos aquela sílaba e aquela (estrofe), precedida pelas *Vyahritis*, ganha o mérito (inteiro) que (a recitação dos) Vedas confere.` },
        { id: 'cm-2-79', number: 'Verso 79', text: `Um homem duas-vezes-nascido que (diariamente) repete aqueles três mil vezes lá fora (da vila), será liberto após um mês mesmo da grande culpa, como uma cobra de sua pele.` },
        { id: 'cm-2-80', number: 'Verso 80', text: `O *Brahmana*, o *Kshatriya*, e o *Vaisya* que negligenciam (a recitação daquela) estrofe-*Rik* e a (realização) oportuna (dos) ritos (prescritos para) eles, serão censurados entre os homens virtuosos.` },
        { id: 'cm-2-81', number: 'Verso 81', text: `Sabe que as três imperecíveis *Mahavyahritis*, precedidas pela sílaba Om, e (seguidas) pela Savitri de três pés são o portal do Veda e o portão que conduz (à união com) Brahman.` },
        { id: 'cm-2-82', number: 'Verso 82', text: `Aquele que diariamente recita aquela (estrofe), incansável, durante três anos, entrará (após a morte) no Brahman mais alto, mover-se-á tão livre quanto o ar, e assumirá uma forma etérea.` },
        { id: 'cm-2-83', number: 'Verso 83', text: `O monossílabo (Om) é o Brahman mais alto, (três) supressões da respiração são a melhor (forma de) austeridade, mas nada supera a Savitri; a veracidade é melhor do que o silêncio.` },
        { id: 'cm-2-84', number: 'Verso 84', text: `Todos os ritos ordenados no Veda, oblações queimadas e (outros) sacrifícios, passam; mas sabe que a sílaba (Om) é imperecível, e (ela é) Brahman, (e) o Senhor das criaturas (Pragapati).` },
        { id: 'cm-2-85', number: 'Verso 85', text: `Uma oferenda, consistindo de orações murmuradas, é dez vezes mais eficaz do que um sacrifício realizado de acordo com as regras (do Veda); uma (oração) que é inaudível (para outros) a supera cem vezes, e a (recitação) mental (de textos sagrados) mil vezes.` },
        { id: 'cm-2-86', number: 'Verso 86', text: `Os quatro *Pakayagnas* e aqueles sacrifícios que são impostos pelas regras (do Veda) não são, todos juntos, iguais em valor a uma décima sexta parte do sacrifício consistindo de orações murmuradas.` },
        { id: 'cm-2-87', number: 'Verso 87', text: `Mas, indubitavelmente, um *Brahmana* alcança a meta mais alta apenas murmurando orações; (quer) ele realize outros (ritos) ou os negligencie, aquele que é amigo (de todas as criaturas) é declarado (ser) um (verdadeiro) *Brahmana*.` },
        { id: 'cm-2-88', number: 'Verso 88', text: `Um homem sábio deve esforçar-se para refrear seus órgãos que correm soltos entre sedutores objetos sensuais, como um cocheiro os seus cavalos.` },
        { id: 'cm-2-89', number: 'Verso 89', text: `Aqueles onze órgãos que antigos sábios nomearam, eu enumerarei adequada (e) precisamente na devida ordem,` },
        { id: 'cm-2-90', number: 'Verso 90', text: `(A saber) o ouvido, a pele, os olhos, a língua, e o nariz como o quinto, o ânus, o órgão de geração, mãos e pés, e o (órgão da) fala, nomeado como o décimo.` },
        { id: 'cm-2-91', number: 'Verso 91', text: `Cinco deles, o ouvido e o resto de acordo com sua ordem, eles chamam de órgãos dos sentidos, e cinco deles, o ânus e o resto, órgãos de ação.` },
        { id: 'cm-2-92', number: 'Verso 92', text: `Sabe que o órgão interno (*manas*) é o décimo primeiro, que por sua qualidade pertence a ambos (os conjuntos); quando esse tiver sido subjugado, ambos os conjuntos de cinco terão sido conquistados.` },
        { id: 'cm-2-93', number: 'Verso 93', text: `Através do apego de seus órgãos (ao prazer sensual) um homem inquestionavelmente incorrerá em culpa; mas se ele os mantiver sob controle completo, ele obterá sucesso (em ganhar todos os seus objetivos).` },
        { id: 'cm-2-94', number: 'Verso 94', text: `O desejo nunca é extinto pelo gozo dos objetos desejados; ele apenas cresce mais forte como um fogo (alimentado) com manteiga clarificada.` },
        { id: 'cm-2-95', number: 'Verso 95', text: `Se um homem devesse obter todos aqueles (gozos sensuais) e outro devesse renunciar a todos eles, a renúncia de todo prazer é muito melhor do que a obtenção deles.` },
        { id: 'cm-2-96', number: 'Verso 96', text: `Aqueles (órgãos) que são fortemente apegados a prazeres sensuais, não podem ser tão eficazmente refreados pela abstinência (de gozos) quanto por uma busca constante do (verdadeiro) conhecimento.` },
        { id: 'cm-2-97', number: 'Verso 97', text: `Nem (o estudo dos) Vedas, nem a liberalidade, nem os sacrifícios, nem qualquer restrição (autoimposta), nem as austeridades, jamais proporcionam a obtenção (de recompensas) a um homem cujo coração é contaminado (pela sensualidade).` },
        { id: 'cm-2-98', number: 'Verso 98', text: `Aquele homem pode ser considerado como tendo (realmente) subjugado seus órgãos, que ao ouvir e tocar e ver, ao provar e cheirar (qualquer coisa) nem se alegra nem se lamenta.` },
        { id: 'cm-2-99', number: 'Verso 99', text: `Mas quando um entre todos os órgãos escapa (do controle), desse modo a sabedoria (do homem) escapa dele, assim como a água (flui) através do único pé (aberto) da pele (odre) de um (carregador de água).` },
        { id: 'cm-2-100', number: 'Verso 100', text: `Se ele mantém todos os (dez) órgãos assim como a mente em sujeição, ele pode ganhar todos os seus objetivos, sem reduzir seu corpo pela (prática) de Yoga.` },
        { id: 'cm-2-101', number: 'Verso 101', text: `Que ele permaneça de pé durante o crepúsculo da manhã, murmurando a Savitri até que o sol apareça, mas (que ele a recite), sentado, à noite até que as constelações possam ser vistas distintamente.` },
        { id: 'cm-2-102', number: 'Verso 102', text: `Aquele que permanece de pé durante o crepúsculo da manhã murmurando (a Savitri), remove a culpa contraída durante a noite (anterior); mas aquele que (a recita), sentado, à noite, destrói o pecado que cometeu durante o dia.` },
        { id: 'cm-2-103', number: 'Verso 103', text: `Mas aquele que não (adora) de pé de manhã, nem sentado à noite, deverá ser excluído, assim como um *Sudra*, de todos os deveres e direitos de um Ariano.` },
        { id: 'cm-2-104', number: 'Verso 104', text: `Aquele que (deseja) realizar a cerimônia (da recitação) diária, pode até mesmo recitar a Savitri perto da água, retirando-se para a floresta, controlando seus órgãos e concentrando sua mente.` },
        { id: 'cm-2-105', number: 'Verso 105', text: `Tanto quando (se estuda) os tratados suplementares do Veda, quanto quando (se recita) a porção diária do Veda, nenhuma consideração precisa ser paga a dias proibidos, igualmente quando (se repete) os textos sagrados exigidos para uma oblação queimada.` },
        { id: 'cm-2-106', number: 'Verso 106', text: `Não há dias proibidos para a recitação diária, visto que essa é declarada ser um *Brahmasattra* (um sacrifício eterno oferecido a Brahman); nisso o Veda toma o lugar das oblações queimadas, e é meritório (mesmo), quando (fenômenos naturais, exigindo) uma cessação do estudo do Veda, tomam o lugar da exclamação *Vashat*.` },
        { id: 'cm-2-107', number: 'Verso 107', text: `Para aquele que, sendo puro e controlando seus órgãos, durante um ano recita diariamente o Veda de acordo com a regra, essa (recitação diária) sempre fará leite doce e azedo, manteiga clarificada e mel fluírem.` },
        { id: 'cm-2-108', number: 'Verso 108', text: `Que um Ariano que tenha sido iniciado, (diariamente) ofereça combustível no fogo sagrado, mendigue alimento, durma no chão e faça o que for benéfico a este professor, até (que ele realize a cerimônia de) *Samavartana* (ao retornar para casa).` },
        { id: 'cm-2-109', number: 'Verso 109', text: `De acordo com a lei sagrada as (seguintes) dez (pessoas, a saber) o filho do professor, aquele que deseja prestar serviço, aquele que transmite conhecimento, aquele que é focado em cumprir a lei, aquele que é puro, uma pessoa conectada por casamento ou amizade, aquele que possui habilidade (mental), aquele que dá presentes em dinheiro, aquele que é honesto, e um parente, podem ser instruídos (no Veda).` },
        { id: 'cm-2-110', number: 'Verso 110', text: `A menos que alguém seja perguntado, não se deve explicar (nada) a ninguém, nem (se deve responder) a uma pessoa que pergunta impropriamente; que um homem sábio, embora conheça (a resposta), comporte-se entre os homens como (se fosse) um idiota.` },
        { id: 'cm-2-111', number: 'Verso 111', text: `Das duas pessoas, aquele que explica ilegalmente (qualquer coisa), e aquele que pergunta ilegalmente (uma questão), um (ou ambos) morrerão ou incorrerão na inimizade (do outro).` },
        { id: 'cm-2-112', number: 'Verso 112', text: `Onde mérito e riqueza não são (obtidos ensinando) nem (pelo menos) a devida obediência, em tal (solo) o conhecimento sagrado não deve ser semeado, assim como uma boa semente (não deve ser atirada) em terra árida.` },
        { id: 'cm-2-113', number: 'Verso 113', text: `Mesmo em tempos de terrível aflição um professor do Veda deveria preferivelmente morrer com seu conhecimento do que semeá-lo em solo árido.` },
        { id: 'cm-2-114', number: 'Verso 114', text: `O Aprendizado Sagrado aproximou-se de um *Brahmana* e disse-lhe: 'Eu sou teu tesouro, preserva-me, não me entregues a um escarnecedor; assim (preservado) eu me tornarei supremamente forte.'` },
        { id: 'cm-2-115', number: 'Verso 115', text: `'Mas entrega-me, como ao guardião de teu tesouro, a um *Brahmana* que tu saibas ser puro, de sentidos subjugados, casto e atento.'` },
        { id: 'cm-2-116', number: 'Verso 116', text: `Mas aquele que adquire sem permissão o Veda daquele que o recita, incorre na culpa de roubar o Veda, e deverá afundar no inferno.` },
        { id: 'cm-2-117', number: 'Verso 117', text: `(Um estudante) deverá primeiro saudar reverencialmente aquele (professor) de quem ele recebe (conhecimento), referindo-se a assuntos mundanos, ao Veda, ou a Brahman.` },
        { id: 'cm-2-118', number: 'Verso 118', text: `Um *Brahmana* que se governa completamente, embora conheça apenas a Savitri, é melhor do que aquele que conhece os três Vedas, (mas) não se controla, come todas as (espécies de) alimento, e vende todas as (espécies de bens).` },
        { id: 'cm-2-119', number: 'Verso 119', text: `Não se deve sentar em um sofá ou assento que um superior ocupa; e aquele que ocupa um sofá ou assento deve levantar-se para ir ao encontro de um (superior), e (depois) saudá-lo.` },
        { id: 'cm-2-120', number: 'Verso 120', text: `Pois os ares vitais de um jovem montam para cima para deixar seu corpo quando um ancião se aproxima; mas ao levantar-se para ir ao seu encontro e saudá-lo ele os recupera.` },
        { id: 'cm-2-121', number: 'Verso 121', text: `Aquele que habitualmente saúda e constantemente presta reverência aos idosos obtém um aumento de quatro (coisas), (a saber) tempo de vida, conhecimento, fama, (e) força.` },
        { id: 'cm-2-122', number: 'Verso 122', text: `Após a (palavra de) saudação, um *Brahmana* que cumprimenta um ancião deve pronunciar seu nome, dizendo, 'Eu sou N. N.'` },
        { id: 'cm-2-123', number: 'Verso 123', text: `Àquelas (pessoas) que, quando um nome é pronunciado, não entendem (o significado da) saudação, um homem sábio deve dizer, 'Sou eu;' e (ele deve se dirigir) da mesma maneira a todas as mulheres.` },
        { id: 'cm-2-124', number: 'Verso 124', text: `Ao saudar ele deve pronunciar após seu nome a palavra *bhoh*; pois os sábios declararam que a natureza de *bhoh* é a mesma da (de todos os) nomes (próprios).` },
        { id: 'cm-2-125', number: 'Verso 125', text: `Um *Brahmana* deve assim ser saudado em retorno, 'Possa tu ser de vida longa, Ó gentil!' e a vogal 'a' deve ser adicionada no final do nome (da pessoa a quem se dirige), sendo a sílaba que a precede prolongada pelo comprimento de três moras.` },
        { id: 'cm-2-126', number: 'Verso 126', text: `Um *Brahmana* que não conhece a forma de retornar uma saudação, não deve ser saudado por um homem erudito; como um *Sudra*, exatamente assim ele é.` },
        { id: 'cm-2-127', number: 'Verso 127', text: `Que ele pergunte a um *Brahmana*, ao encontrá-lo, sobre (sua saúde, com a palavra) *kusala*, a um *Kshatriya* (com a palavra) *anamaya*, a um *Vaisya* (com a palavra) *kshema*, e a um *Sudra* (com a palavra) *anarogya*.` },
        { id: 'cm-2-128', number: 'Verso 128', text: `Aquele que foi iniciado (para realizar um sacrifício *Srauta*) não deve ser chamado por seu nome, ainda que seja um homem mais jovem; aquele que conhece a lei sagrada deve usar, ao falar com tal (homem, a partícula) *bhoh* e (o pronome) *bhavat* (vossa adoração).` },
        { id: 'cm-2-129', number: 'Verso 129', text: `Mas a uma fêmea que é a esposa de outro homem, e não uma parente de sangue, ele deve dizer, 'Senhora' (*bhavati*) ou 'Amada irmã!'` },
        { id: 'cm-2-130', number: 'Verso 130', text: `Aos seus tios maternos e paternos, sogros, sacerdotes oficiantes, (e outras) pessoas veneráveis, ele deve dizer, 'Eu sou N. N.,' e levantar-se (para encontrá-los), ainda que sejam mais jovens (que ele mesmo).` },
        { id: 'cm-2-131', number: 'Verso 131', text: `Uma tia materna, a esposa de um tio materno, uma sogra, e uma tia paterna devem ser honradas como a esposa de seu professor; elas são iguais à esposa de seu professor.` },
        { id: 'cm-2-132', number: 'Verso 132', text: `(Os pés da) esposa de seu irmão, se ela for da mesma casta (*varna*), devem ser abraçados todos os dias; mas (os pés das) esposas de (outros) parentes paternos e maternos precisam ser apenas abraçados em seu retorno de uma jornada.` },
        { id: 'cm-2-133', number: 'Verso 133', text: `Para com a irmã de seu pai e de sua mãe, e para com a sua própria irmã mais velha, deve-se comportar como para com a sua mãe; (mas) a mãe é mais venerável do que elas.` },
        { id: 'cm-2-134', number: 'Verso 134', text: `Concidadãos são chamados amigos (e iguais embora um seja) dez anos (mais velho que o outro), homens praticando (a mesma) bela arte (embora um seja) cinco anos (mais velho que o outro), *Srotriyas* (embora) três anos (intervenham entre suas idades), mas parentes de sangue apenas (se a) diferença de idade for muito pequena.` },
        { id: 'cm-2-135', number: 'Verso 135', text: `Sabe que um *Brahmana* de dez anos e um *Kshatriya* de cem anos estão um para o outro na relação de pai e filho; mas entre aqueles dois o *Brahmana* é o pai.` },
        { id: 'cm-2-136', number: 'Verso 136', text: `Riqueza, parentesco, idade, (a devida realização de) ritos, e, em quinto lugar, aprendizado sagrado são títulos para respeito; mas cada (causa) nomeada mais tarde é mais importante (do que as precedentes).` },
        { id: 'cm-2-137', number: 'Verso 137', text: `Qualquer homem das três castas (mais altas) que possua mais dessas cinco, tanto em número quanto em grau, esse homem é digno de honra entre eles; e (assim é) também um *Sudra* que tenha entrado na décima (década de sua vida).` },
        { id: 'cm-2-138', number: 'Verso 138', text: `Deve-se abrir caminho para um homem em uma carruagem, para aquele que tem acima de noventa anos, para um doente, para o portador de um fardo, para uma mulher, para um *Snataka*, para o rei, e para um noivo.` },
        { id: 'cm-2-139', number: 'Verso 139', text: `Entre todos esses, se eles se encontrarem (ao mesmo tempo), um *Snataka* e o rei devem ser (mais) honrados; e se o rei e um *Snataka* (se encontrarem), o último recebe respeito do rei.` },
        { id: 'cm-2-140', number: 'Verso 140', text: `Eles chamam aquele *Brahmana* que inicia um pupilo e lhe ensina o Veda junto com o *Kalpa* e as *Rahasyas*, o professor (*akarya*, do último).` },
        { id: 'cm-2-141', number: 'Verso 141', text: `Mas aquele que para seu sustento ensina apenas uma porção do Veda, ou também os *Angas* do Veda, é chamado o subprofessor (*upadhyaya*).` },
        { id: 'cm-2-142', number: 'Verso 142', text: `Aquele *Brahmana*, que realiza de acordo com as regras (do Veda) os ritos, o *Garbhadhana* (rito de concepção), e assim por diante, e dá alimento (à criança), é chamado o Guru (o venerável).` },
        { id: 'cm-2-143', number: 'Verso 143', text: `Aquele que, sendo (devidamente) escolhido (para o propósito), realiza o *Agnyadheya*, os *Pakayagnas*, (e) os sacrifícios (*Srauta*), como o *Agnishtoma* (para outro homem), é chamado (seu) sacerdote oficiante.` },
        { id: 'cm-2-144', number: 'Verso 144', text: `Aquele (homem) que verdadeiramente preenche ambos os seus ouvidos com o Veda, (o pupilo) considerará como seu pai e mãe; ele nunca deve ofendê-lo.` },
        { id: 'cm-2-145', number: 'Verso 145', text: `O professor (*akarya*) é dez vezes mais venerável do que um subprofessor (*upadhyaya*), o pai cem vezes mais do que o professor, mas a mãe mil vezes mais do que o pai.` },
        { id: 'cm-2-146', number: 'Verso 146', text: `Daquele que dá o nascimento natural e aquele que dá (o conhecimento) do Veda, o doador do Veda é o pai mais venerável; pois o nascimento pela causa do Veda (garante) (recompensas) eternas tanto nesta (vida) quanto após a morte.` },
        { id: 'cm-2-147', number: 'Verso 147', text: `Que ele considere que (recebeu) uma (mera) existência (animal), quando seus pais o geraram através de afeto mútuo, e quando ele nasceu do útero (de sua mãe).` },
        { id: 'cm-2-148', number: 'Verso 148', text: `Mas aquele nascimento que um professor inteirado de todo o Veda, de acordo com a lei, obtém para ele através da Savitri, é real, isento da velhice e da morte.` },
        { id: 'cm-2-149', number: 'Verso 149', text: `(O pupilo) deve saber que aquele homem também que o beneficia por (instrução no) Veda, seja pouco ou muito, é chamado nestes (Institutos) de seu Guru, em consequência desse benefício (conferido por instrução no) Veda.` },
        { id: 'cm-2-150', number: 'Verso 150', text: `Aquele *Brahmana* que é o doador do nascimento pela causa do Veda e o professor dos deveres prescritos torna-se pela lei o pai de um homem idoso, mesmo que ele próprio seja uma criança.` },
        { id: 'cm-2-151', number: 'Verso 151', text: `O jovem Kavi, o filho de Angiras, ensinou os seus (parentes que eram velhos o bastante para serem) pais, e, como ele os superava em conhecimento (sagrado), ele os chamou de 'Filhinhos'.` },
        { id: 'cm-2-152', number: 'Verso 152', text: `Eles, movidos por ressentimento, perguntaram aos deuses a respeito daquela matéria, e os deuses, tendo se reunido, responderam, 'A criança dirigiu-se a vocês apropriadamente.'` },
        { id: 'cm-2-153', number: 'Verso 153', text: `'Pois (um homem) destituído de conhecimento (sagrado) é de fato uma criança, e aquele que lhe ensina o Veda é seu pai; pois (os sábios) sempre disseram "criança" a um homem ignorante, e "pai" a um professor do Veda.'` },
        { id: 'cm-2-154', number: 'Verso 154', text: `Nem através dos anos, nem através de (cabelos) brancos, nem através da riqueza, nem através de parentes (poderosos) (vem a grandeza). Os sábios fizeram esta lei, 'Aquele que aprendeu o Veda junto com os *Angas* (*Anukana*) é (considerado) grande por nós.'` },
        { id: 'cm-2-155', number: 'Verso 155', text: `A antiguidade dos *Brahmanas* vem do conhecimento (sagrado), a dos *Kshatriyas* do valor, a dos *Vaisyas* da riqueza em grãos (e outros bens), mas a dos *Sudras* apenas da idade.` },
        { id: 'cm-2-156', number: 'Verso 156', text: `Um homem não é, portanto, (considerado) venerável porque sua cabeça é grisalha; àquele que, embora jovem, aprendeu o Veda, os deuses consideram ser venerável.` },
        { id: 'cm-2-157', number: 'Verso 157', text: `Como um elefante feito de madeira, como um antílope feito de couro, tal é um *Brahmana* ignorante; aqueles três não têm nada a não ser os nomes (de sua espécie).` },
        { id: 'cm-2-158', number: 'Verso 158', text: `Como um eunuco é improdutivo com mulheres, como uma vaca com uma vaca é infecunda, e como um dom dado a um homem ignorante não rende recompensa, exatamente assim é um *Brahmana* inútil, que não (conhece) os *Rikas*.` },
        { id: 'cm-2-159', number: 'Verso 159', text: `Seres criados devem ser instruídos no (que concerne) ao seu bem-estar sem lhes causar dor, e fala doce e gentil deve ser usada por (um professor) que deseja (acatar) a lei sagrada.` },
        { id: 'cm-2-160', number: 'Verso 160', text: `Ele, por certo, cuja fala e pensamentos são puros e sempre perfeitamente guardados, ganha a recompensa inteira que é conferida pelo Vedanta.` },
        { id: 'cm-2-161', number: 'Verso 161', text: `Que ele não, mesmo estando em dor, (fale palavras) que cortem (outros) no vivo; que ele não fira outros em pensamento ou ato; que ele não profira falas que tornem (outros) com medo dele, visto que isso o impedirá de ganhar o céu.` },
        { id: 'cm-2-162', number: 'Verso 162', text: `Um *Brahmana* deveria sempre temer a homenagem como se fosse veneno; e constantemente desejar (sofrer) o escárnio como (ele ansiaria por) néctar.` },
        { id: 'cm-2-163', number: 'Verso 163', text: `Pois aquele que é escarnecido (não obstante pode) dormir com a mente tranquila, acordar com a mente tranquila, e com a mente tranquila caminhar aqui entre os homens; mas o escarnecedor perece inteiramente.` },
        { id: 'cm-2-164', number: 'Verso 164', text: `Um homem duas-vezes-nascido que foi santificado pelo (emprego dos) meios, (descritos acima) na devida ordem, deverá gradual e cumulativamente realizar as várias austeridades prescritas para (aqueles que) estudam o Veda.` },
        { id: 'cm-2-165', number: 'Verso 165', text: `Um Ariano deve estudar todo o Veda junto com as *Rahasyas*, realizando ao mesmo tempo vários tipos de austeridades e os votos prescritos pelas regras (do Veda).` },
        { id: 'cm-2-166', number: 'Verso 166', text: `Que um *Brahmana* que deseja realizar austeridades, repita constantemente o Veda; pois o estudo do Veda é declarado (ser) neste mundo a mais alta austeridade para um *Brahmana*.` },
        { id: 'cm-2-167', number: 'Verso 167', text: `Em verdade, aquele homem duas-vezes-nascido realiza a mais alta austeridade até as extremidades de suas unhas, o qual, embora usando uma guirlanda, diariamente recita o Veda em particular até o máximo de sua capacidade.` },
        { id: 'cm-2-168', number: 'Verso 168', text: `Um homem duas-vezes-nascido que, não tendo estudado o Veda, aplica-se a outro (e mundano estudo), logo cai, mesmo enquanto vive, à condição de um *Sudra* e seus descendentes (depois dele).` },
        { id: 'cm-2-169', number: 'Verso 169', text: `De acordo com a injunção dos textos revelados, o primeiro nascimento de um Ariano é de (sua natural) mãe, o segundo (acontece) na amarração do cinto de grama *Munga*, e o terceiro na iniciação (à realização) de um sacrifício (*Srauta*).` },
        { id: 'cm-2-170', number: 'Verso 170', text: `Entre esses (três) o nascimento que é simbolizado pela investidura com o cinto de grama *Munga*, é seu nascimento pela causa do Veda; eles declaram que naquele (nascimento) a (estrofe) *Savitri* é sua mãe e o professor seu pai.` },
        { id: 'cm-2-171', number: 'Verso 171', text: `Eles chamam o professor de pai (do pupilo) porque ele dá o Veda; pois ninguém pode realizar um rito (sagrado) antes da investidura com o cinto de grama *Munga*.` },
        { id: 'cm-2-172', number: 'Verso 172', text: `(Aquele que não foi iniciado) não deve pronunciar (nenhum) texto Védico excetuando (aqueles exigidos para) a realização de ritos fúnebres, visto que ele está no mesmo nível de um *Sudra* antes de seu nascimento pelo Veda.` },
        { id: 'cm-2-173', number: 'Verso 173', text: `O (estudante) que foi iniciado deve ser instruído na realização dos votos, e gradualmente aprender o Veda, observando as regras prescritas.` },
        { id: 'cm-2-174', number: 'Verso 174', text: `Qualquer veste de pele, cordão sagrado, cinto, cajado, e veste inferior que sejam prescritos para um (estudante na iniciação), o mesmo (deve novamente ser usado) na (realização dos) votos.` },
        { id: 'cm-2-175', number: 'Verso 175', text: `Mas um estudante que reside com seu professor deve observar as seguintes regras restritivas, controlando devidamente todos os seus órgãos, a fim de aumentar seu mérito espiritual.` },
        { id: 'cm-2-176', number: 'Verso 176', text: `Todos os dias, tendo se banhado, e sendo purificado, ele deve oferecer libações de água aos deuses, sábios e manes, adorar (as imagens dos) deuses, e colocar combustível no (fogo sagrado).` },
        { id: 'cm-2-177', number: 'Verso 177', text: `Que ele se abstenha de mel, carne, perfumes, guirlandas, substâncias (usadas para) dar sabor (ao alimento), mulheres, todas as substâncias que se tornaram ácidas, e de causar ferimento a criaturas vivas.` },
        { id: 'cm-2-178', number: 'Verso 178', text: `De ungir (seu corpo), aplicar colírio em seus olhos, do uso de sapatos e de um guarda-chuva (ou sombrinha), do desejo (sensual), ira, cobiça, de dançar, cantar, e tocar (instrumentos musicais),` },
        { id: 'cm-2-179', number: 'Verso 179', text: `De jogos de azar, disputas ociosas, maledicência, e mentira, de olhar e tocar mulheres, e de ferir outros.` },
        { id: 'cm-2-180', number: 'Verso 180', text: `Que ele sempre durma sozinho, que ele nunca desperdice sua virilidade; pois aquele que voluntariamente desperdiça sua virilidade, quebra seu voto.` },
        { id: 'cm-2-181', number: 'Verso 181', text: `Um estudante duas-vezes-nascido, que involuntariamente desperdiçou sua força viril durante o sono, deve banhar-se, adorar o sol, e depois murmurar três vezes a estrofe-*Rik* (que começa), 'Novamente que minha força retorne a mim.'` },
        { id: 'cm-2-182', number: 'Verso 182', text: `Que ele busque um pote cheio de água, flores, esterco de vaca, terra, e grama *Kusa*, tanto quanto possa ser exigido (pelo seu professor), e diariamente vá pedir alimento.` },
        { id: 'cm-2-183', number: 'Verso 183', text: `Um estudante, sendo puro, deverá diariamente trazer alimento das casas de homens que não são deficientes no (conhecimento do) Veda e na (realização de) sacrifícios, e que são famosos por (seguirem suas lícitas) ocupações.` },
        { id: 'cm-2-184', number: 'Verso 184', text: `Que ele não mendigue dos parentes de seu professor, nem dos seus próprios ou dos parentes de sangue de sua mãe; mas se não houver casas pertencentes a estranhos, que ele vá a uma daquelas nomeadas acima, tomando a nomeada por último primeiro;` },
        { id: 'cm-2-185', number: 'Verso 185', text: `Ou, se não houver (homens virtuosos do tipo) mencionado acima, ele pode ir a cada (casa na) vila, sendo puro e permanecendo em silêncio; mas que ele evite os *Abhisastas* (aqueles acusados de pecado mortal).` },
        { id: 'cm-2-186', number: 'Verso 186', text: `Tendo trazido combustível sagrado de uma distância, que ele o coloque em qualquer lugar exceto no chão, e que ele, incansável, faça com ele oblações queimadas ao fogo sagrado, tanto à noite quanto de manhã.` },
        { id: 'cm-2-187', number: 'Verso 187', text: `Aquele que, sem estar doente, negligencia durante sete dias (sucessivos) de sair para mendigar, e de oferecer combustível no fogo sagrado, deverá realizar a penitência de um *Avakirnin* (aquele que quebrou seu voto).` },
        { id: 'cm-2-188', number: 'Verso 188', text: `Aquele que realiza o voto (de aprendizado) deverá subsistir constantemente de esmolas, (mas) não comer o alimento de uma (pessoa apenas); a subsistência de um estudante em alimento mendigado é declarada ser igual (em mérito) ao jejum.` },
        { id: 'cm-2-189', number: 'Verso 189', text: `A seu bel-prazer ele pode comer, quando convidado, o alimento de um homem em (um rito) em honra aos deuses, observando (entretanto as condições de seu voto), ou em uma (refeição fúnebre) em honra aos manes, comportando-se (entretanto) como um eremita.` },
        { id: 'cm-2-190', number: 'Verso 190', text: `Este dever é prescrito pelos sábios apenas para um *Brahmana*; mas nenhum dever semelhante é ordenado para um *Kshatriya* e um *Vaisya*.` },
        { id: 'cm-2-191', number: 'Verso 191', text: `Tanto quando ordenado por seu professor, quanto sem um comando (especial), (um estudante) deverá sempre se esforçar em estudar (o Veda), e em fazer o que é proveitoso ao seu professor.` },
        { id: 'cm-2-192', number: 'Verso 192', text: `Controlando seu corpo, sua fala, seus órgãos (dos sentidos), e sua mente, que ele permaneça de pé com as mãos juntas, olhando para a face de seu professor.` },
        { id: 'cm-2-193', number: 'Verso 193', text: `Que ele sempre mantenha seu braço direito descoberto, comporte-se decentemente e mantenha seu corpo bem coberto, e quando lhe for dirigido (com as palavras), 'Sente-se', ele deverá sentar-se, de frente para o seu professor.` },
        { id: 'cm-2-194', number: 'Verso 194', text: `Na presença de seu professor, que ele sempre coma menos, use uma veste e ornamentos menos valiosos (do que o primeiro), e que ele se levante mais cedo (de sua cama), e vá descansar mais tarde.` },
        { id: 'cm-2-195', number: 'Verso 195', text: `Que ele não responda ou converse com (seu professor), reclinando-se em uma cama, nem sentado, nem comendo, nem de pé, nem com a face desviada.` },
        { id: 'cm-2-196', number: 'Verso 196', text: `Que ele faça (isso), levantando-se, se (seu professor) estiver sentado, avançando em direção a ele quando ele estiver de pé, indo encontrá-lo se ele avançar, e correndo atrás dele quando ele correr;` },
        { id: 'cm-2-197', number: 'Verso 197', text: `Indo (ao redor) para ficar de frente (para o professor), se sua face estiver desviada, aproximando-se dele se ele estiver a uma distância, mas curvando-se em direção a ele se ele deitar em uma cama, e se ele estiver em um lugar mais baixo.` },
        { id: 'cm-2-198', number: 'Verso 198', text: `Quando seu professor estiver próximo, que sua cama ou assento seja baixo; mas à vista de seu professor ele não deverá sentar-se descuidadamente à vontade.` },
        { id: 'cm-2-199', number: 'Verso 199', text: `Que ele não pronuncie o mero nome de seu professor (sem adicionar um título honorífico) mesmo pelas suas costas, e que ele não imite seu andar, fala, e comportamento.` },
        { id: 'cm-2-200', number: 'Verso 200', text: `Onde quer que (as pessoas) censurem justamente ou difamem falsamente seu professor, ali ele deve cobrir seus ouvidos ou partir dali para outro lugar.` },
        { id: 'cm-2-201', number: 'Verso 201', text: `Por censurar (seu professor), embora justamente, ele se tornará (em seu próximo nascimento) um asno, por difamá-lo falsamente, um cão; aquele que vive da substância de seu professor, se tornará um verme, e aquele que é invejoso (de seu mérito), um inseto (maior).` },
        { id: 'cm-2-202', number: 'Verso 202', text: `Ele não deve servir o (professor pela intervenção de outro) enquanto ele mesmo se mantém distante, nem quando ele (mesmo) estiver zangado, nem quando uma mulher estiver perto; se ele estiver sentado em uma carruagem ou em um assento (elevado), ele deve descer e depois saudar seu (professor).` },
        { id: 'cm-2-203', number: 'Verso 203', text: `Que ele não se sente com seu professor, a sotavento ou a barlavento (dele); nem que ele diga algo que seu professor não possa ouvir.` },
        { id: 'cm-2-204', number: 'Verso 204', text: `Ele pode sentar-se com seu professor em uma carruagem puxada por bois, cavalos, ou camelos, em um terraço, em uma cama de grama ou folhas, em uma esteira, em uma rocha, em um banco de madeira, ou em um barco.` },
        { id: 'cm-2-205', number: 'Verso 205', text: `Se o professor de seu professor estiver perto, que ele se comporte (para com ele) como para com o seu próprio professor; mas que ele, a menos que tenha recebido permissão de seu professor, não saúde pessoas veneráveis de sua própria (família).` },
        { id: 'cm-2-206', number: 'Verso 206', text: `Este é igualmente (ordenado como) seu comportamento constante para com (outros) instrutores na ciência, para com seus parentes (a quem honra é devida), para com todos que possam contê-lo do pecado, ou possam lhe dar um conselho salutar.` },
        { id: 'cm-2-207', number: 'Verso 207', text: `Para com seus superiores que ele sempre se comporte como para com seu professor, igualmente para com os filhos de seu professor, nascidos de esposas de casta igual, e para com os parentes do professor tanto do lado do pai quanto do lado da mãe.` },
        { id: 'cm-2-208', number: 'Verso 208', text: `O filho do professor que transmite instrução (no lugar de seu pai), quer seja mais jovem ou de idade igual, ou um estudante da (ciência dos) sacrifícios (ou de outros *Angas*), merece a mesma honra que o professor.` },
        { id: 'cm-2-209', number: 'Verso 209', text: `(Um estudante) não deve massagear os membros do filho de seu professor, nem ajudá-lo a se banhar, nem comer os fragmentos de sua comida, nem lavar seus pés.` },
        { id: 'cm-2-210', number: 'Verso 210', text: `As esposas do professor, que pertencem à mesma casta, devem ser tratadas tão respeitosamente quanto o professor; mas aquelas que pertencem a uma casta diferente, devem ser honradas levantando-se e com saudação.` },
        { id: 'cm-2-211', number: 'Verso 211', text: `Que ele não realize para uma esposa de seu professor (os ofícios de) ungi-la, ajudá-la no banho, massagear seus membros, ou arrumar seu cabelo.` },
        { id: 'cm-2-212', number: 'Verso 212', text: `(Um pupilo) que tem vinte anos completos, e sabe o que é adequado e inadequado, não deverá saudar uma jovem esposa de seu professor (abraçando) seus pés.` },
        { id: 'cm-2-213', number: 'Verso 213', text: `É da natureza das mulheres seduzir os homens neste (mundo); por essa razão os sábios nunca estão desguarnecidos na (companhia de) fêmeas.` },
        { id: 'cm-2-214', number: 'Verso 214', text: `Pois as mulheres são capazes de desviar neste (mundo) não apenas um tolo, mas mesmo um homem erudito, e (fazer) dele um escravo do desejo e da ira.` },
        { id: 'cm-2-215', number: 'Verso 215', text: `Não se deve sentar em um lugar solitário com a própria mãe, irmã, ou filha; pois os sentidos são poderosos, e dominam até mesmo um homem erudito.` },
        { id: 'cm-2-216', number: 'Verso 216', text: `Mas a seu bel-prazer um jovem estudante pode prostrar-se no chão perante a jovem esposa de um professor, de acordo com a regra, e dizer: 'Eu, N. N., (te adoro, Ó senhora).'` },
        { id: 'cm-2-217', number: 'Verso 217', text: `Ao retornar de uma jornada ele deve abraçar os pés da esposa de seu professor e diariamente saudá-la (na maneira recém-mencionada), lembrando-se do dever dos virtuosos.` },
        { id: 'cm-2-218', number: 'Verso 218', text: `Assim como o homem que cava com uma pá (no chão) obtém água, exatamente assim um (pupilo) obediente obtém o conhecimento que jaz (escondido) em seu professor.` },
        { id: 'cm-2-219', number: 'Verso 219', text: `Um (estudante) pode quer raspar sua cabeça, ou usar seu cabelo em tranças, ou trançar uma mecha no topo de sua cabeça; o sol nunca deve se pôr ou nascer enquanto ele (jaz adormecido) na vila.` },
        { id: 'cm-2-220', number: 'Verso 220', text: `Se o sol nascer ou se pôr enquanto ele estiver dormindo, seja (que ele ofendeu) intencionalmente ou não intencionalmente, ele deverá jejuar durante o (próximo) dia, murmurando (a *Savitri*).` },
        { id: 'cm-2-221', number: 'Verso 221', text: `Pois aquele que jaz (dormindo), enquanto o sol se põe ou nasce, e não realiza (aquela) penitência, é maculado por grande culpa.` },
        { id: 'cm-2-222', number: 'Verso 222', text: `Purificado sorvendo água, ele deverá diariamente adorar durante ambos os crepúsculos com a mente concentrada em um lugar puro, murmurando o texto prescrito de acordo com a regra.` },
        { id: 'cm-2-223', number: 'Verso 223', text: `Se uma mulher ou um homem de casta baixa realizar qualquer coisa (que conduza) à felicidade, que ele a pratique diligentemente, assim como (qualquer outro ato permitido) no qual seu coração encontre prazer.` },
        { id: 'cm-2-224', number: 'Verso 224', text: `(Alguns declaram que) o bem principal consiste na (aquisição de) mérito espiritual e riqueza, (outros o colocam) na (gratificação do) desejo e (na aquisição de) riqueza, (outros) no (mérito espiritual) apenas, e (outros dizem que a aquisição de) riqueza apenas é o bem principal aqui (embaixo); mas a decisão (correta) é que consiste no agregado desses três.` },
        { id: 'cm-2-225', number: 'Verso 225', text: `O professor, o pai, a mãe, e um irmão mais velho não devem ser tratados com desrespeito, especialmente por um *Brahmana*, embora um seja gravemente ofendido (por eles).` },
        { id: 'cm-2-226', number: 'Verso 226', text: `O professor é a imagem de Brahman, o pai a imagem de *Pragapati* (o senhor dos seres criados), a mãe a imagem da terra, e um irmão consanguíneo (mais velho) a imagem de si mesmo.` },
        { id: 'cm-2-227', number: 'Verso 227', text: `Esse trabalho (e dor) que os pais sofrem no nascimento de (seus) filhos, não pode ser compensado nem em cem anos.` },
        { id: 'cm-2-228', number: 'Verso 228', text: `Que ele sempre faça o que é agradável a esses (dois) e sempre (o que possa agradar) ao seu professor; quando esses três estão satisfeitos, ele obtém todas (aquelas recompensas que) as austeridades (rendem).` },
        { id: 'cm-2-229', number: 'Verso 229', text: `A obediência para com esses três é declarada ser a melhor (forma de) austeridade; que ele não realize outros atos meritórios sem a permissão deles.` },
        { id: 'cm-2-230', number: 'Verso 230', text: `Pois eles são declarados serem os três mundos, eles as três ordens (principais), eles os três Vedas, e eles os três fogos sagrados.` },
        { id: 'cm-2-231', number: 'Verso 231', text: `O pai, por certo, é declarado ser o fogo *Garhapatya*, a mãe o *Dakshinagni*, mas o professor o fogo *Ahavaniya*; esta tríade de fogos é a mais venerável.` },
        { id: 'cm-2-232', number: 'Verso 232', text: `Aquele que não negligencia esses três, (mesmo depois de ter se tornado) um chefe de família, conquistará os três mundos e, radiante em corpo como um deus, ele desfrutará de bem-aventurança no céu.` },
        { id: 'cm-2-233', number: 'Verso 233', text: `Honrando sua mãe ele ganha este mundo (inferior), honrando seu pai a esfera média, mas pela obediência ao seu professor o mundo de Brahman.` },
        { id: 'cm-2-234', number: 'Verso 234', text: `Todos os deveres foram cumpridos por aquele que honra a esses três; mas para aquele que não os honra, todos os ritos permanecem infrutíferos.` },
        { id: 'cm-2-235', number: 'Verso 235', text: `Enquanto esses três viverem, por tanto tempo que ele não realize (independentemente) quaisquer outros (atos meritórios); que ele sempre os sirva, alegrando-se (em fazer o que é) agradável e benéfico (a eles).` },
        { id: 'cm-2-236', number: 'Verso 236', text: `Ele deverá informá-los de tudo que com seu consentimento ele possa realizar em pensamento, palavra, ou ato por causa do próximo mundo.` },
        { id: 'cm-2-237', number: 'Verso 237', text: `Por (honrar) a estes três tudo que deve ser feito pelo homem, é realizado; esse é claramente o dever mais alto, todo outro (ato) é um dever subordinado.` },
        { id: 'cm-2-238', number: 'Verso 238', text: `Aquele que possui fé pode receber aprendizado puro mesmo de um homem de casta inferior, a lei mais alta mesmo do mais baixo, e uma esposa excelente mesmo de uma família vil.` },
        { id: 'cm-2-239', number: 'Verso 239', text: `Mesmo do veneno o néctar pode ser tirado, mesmo de uma criança um bom conselho, mesmo de um inimigo (uma lição de) boa conduta, e mesmo de uma (substância) impura o ouro.` },
        { id: 'cm-2-240', number: 'Verso 240', text: `Esposas excelentes, aprendizado, (o conhecimento da) lei, (as regras de) pureza, bons conselhos, e várias artes podem ser adquiridos de qualquer pessoa.` },
        { id: 'cm-2-241', number: 'Verso 241', text: `É prescrito que em tempos de aflição (um estudante) pode aprender (o Veda) de alguém que não é um *Brahmana*; e que ele deverá andar atrás e servir (tal) professor, enquanto a instrução durar.` },
        { id: 'cm-2-242', number: 'Verso 242', text: `Aquele que deseja incomparável bem-aventurança (no céu) não deverá habitar durante toda a sua vida na (casa de) um professor não-*Brahmânico*, nem com um *Brahmana* que não conhece todo o Veda e os *Angas*.` },
        { id: 'cm-2-243', number: 'Verso 243', text: `Mas se (um estudante) desejar passar toda a sua vida na casa do professor, ele deve servi-lo diligentemente, até que ele seja liberto deste corpo.` },
        { id: 'cm-2-244', number: 'Verso 244', text: `Um *Brahmana* que serve seu professor até a dissolução de seu corpo, alcança imediatamente a eterna mansão de Brahman.` },
        { id: 'cm-2-245', number: 'Verso 245', text: `Aquele que conhece a lei sagrada não deve apresentar nenhum presente ao seu professor antes (do *Samavartana*); mas quando, com a permissão de seu professor, ele estiver prestes a tomar o banho (final), que ele obtenha (um presente) para o venerável homem de acordo com sua habilidade,` },
        { id: 'cm-2-246', number: 'Verso 246', text: `(A saber) um campo, ouro, uma vaca, um cavalo, uma sombrinha e sapatos, um assento, grãos, (mesmo) vegetais, (e assim) dê prazer ao seu professor.` },
        { id: 'cm-2-247', number: 'Verso 247', text: `(Um estudante perpétuo) deve, se seu professor morrer, servir ao seu filho (desde que seja) dotado de boas qualidades, ou à sua viúva, ou ao seu *Sapinda*, da mesma maneira que ao professor.` },
        { id: 'cm-2-248', number: 'Verso 248', text: `Se nenhum destes estiver vivo, ele deve servir ao fogo sagrado, de pé (de dia) e sentado (durante a noite), e assim terminar sua vida.` },
        { id: 'cm-2-249', number: 'Verso 249', text: `Um *Brahmana* que assim passa sua vida como um estudante sem quebrar seu voto, alcança (após a morte) a morada mais alta e não nascerá novamente neste mundo.` },
      ],
    },
  ],
};
